"use strict";

// tabela | matheus alves
// https://github.com/theuves/tabela

var colors = require("colors");

module.exports = function (tab, options) {
  options = options || {};

  // Alinhamento e cor.
  var alignment = options.alignment;
  var color = options.color;

  // Verifica se `tab` existe.
  if (!tab.length) {
    return;
  }

  // Verifica se `tab` é uma array.
  if (!Array.isArray(tab)) {
    return;
  }

  // Navega entre todos os elementos da array.
  for (var i in tab) {

    // Todos os elementos da array também devem
    // ser arrays, caso contrário retornará `undefined`.
    if (!Array.isArray(tab[i])) {
      return; // :-)
    } else {

      // Converte em string todos os valores
      // da array da array.
      tab[i] = tab[i].map(function (j) {
        return j.toString();
      });
    }
  }

  // A variável `n` armazenará o tamanho da
  // maior array (de dentro da array).
  var n = 0;

  for (var i in tab) {
    if (tab[i].length > n) {
      n = tab[i].length; // :-)
    }
  }

  // Deixa todas as arrays da array com o
  // mesmo tamanho.
  for (var i in tab) {

    // Se a array [`tab[i]`] for menor.
    if (tab[i].length < n) {

      // Adiciona elementos nessa array [menor]
      // para deixá-la com o mesmo tamanho das outras.
      while (tab[i].length < n) {
        tab[i].push("");
      }
    }
  }

  var m; // :-)

  // Navega entre as arrays.
  for (var i in tab) {

    // A variável `m` armazenará o comprimento da
    // maior string (dessa array *_*).
    m = 0;

    for (var j in tab[i]) {
      if (tab[i][j].length > m) {
        m = tab[i][j].length; // :-)
      }
    }

    for (var j in tab[i]) {

      // A variável `x` será igual ao tamanho
      // dos espaços que sobram da string maior.
      var x = m - tab[i][j].length;

      // Apenas um espaço.
      var s = " ";

      // Se for para centralizar o texto.
      if (alignment === "center") {
        var d, e;

        // Distribui espaços para direita e
        // esquerda para centralizar texto.
        if (x % 2 === 0) {
          d = x / 2;
          e = x / 2;
        } else {
          d = x / 2 - 0.5;
          e = x / 2 + 0.5;
        }

        tab[i][j] = s.repeat(d) + tab[i][j] + s.repeat(e);

      // Se for para alinhar a direita.
      } else if (alignment === "right") {
        tab[i][j] = s.repeat(x) + tab[i][j];

      // Senão (por padrão) alinha a esquerda.
      } else {
        tab[i][j] += s.repeat(x);
      }

      // Se ainda estiver na primeira array, ou
      // seja no cabeçalho.
      if (j === "0") {

        // Expressão regular para válidar a cor.
        var re = new RegExp("(" + ([
          "black", "red", "green",
          "yellow", "blue", "magenta",
          "cyan", "white", "gr[ae]y"
        ].join("|")) + ")", "i");

        // Se for para adicionar cor.
        if (color) {

          // Verifica se a cor é válida.
          if (re.test(color)) {

            // Colorir.
            tab[i][j] = eval("tab[i][j]." + color);
          }
        }
      }

      tab[i][j] = s + tab[i][j] + " |";
    }
  }

  // Cria barra para dividir cabeçalho.
  for (var i in tab) {
    var barra = [];

    for (var j in tab[i]) {
      var largura = tab[i][j].length - 1;

      if (j === "1") {
        barra.push("-".repeat(largura) + "|");
      }

      barra.push(tab[i][j]);
    }

    tab[i] = barra;
  }

  // Adiciona laterais da esquerda.
  for (var i in tab[0]) {
    tab[0][i] = "|" + tab[0][i];
  }

  var arr = [];

  n += 1;

  // Ordena a tabela.
  for (var i = 0; i < n; i++) {
    var t = [];

    for (var j in tab) {
      t.push(tab[j][i]);
    }

    arr.push(t);
  }

  tab = arr;
  arr = [];

  // Junta a array.
  for (var i in tab) {
    arr.push(tab[i].join(""));
  }

  tab = arr;

  // Adiciona as barras.
  n = tab[1].length;
  var b = "+" + "-".repeat(n - 2) + "+";

  return b + "\n" + tab.join("\n") + "\n" + b;
};
